import * as fs from "fs";

const data = fs.readFileSync(0, "latin1");
const lines = data.split("\n");
let start = -1;
for (let i = 0; i < lines.length; i++) {
  if (lines[i].startsWith(">THREE")) { start = i + 1; break; }
}
const parts: string[] = [];
if (start >= 0) {
  for (let i = start; i < lines.length; i++) {
    const l = lines[i];
    if (l.length > 0 && l[0] === ">") break;
    const t = l.trim();
    if (t.length) parts.push(t);
  }
}
const seq = parts.join("").toUpperCase();
const n = seq.length;

function freq(k: number): string {
  const m = new Map<string, number>();
  for (let i = 0; i + k <= n; i++) {
    const s = seq.substr(i, k);
    m.set(s, (m.get(s) || 0) + 1);
  }
  const total = n - k + 1;
  const arr = Array.from(m.entries());
  arr.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  let out = "";
  for (const [key, c] of arr) {
    out += key + " " + ((c * 100) / total).toFixed(3) + "\n";
  }
  return out + "\n";
}

function count(f: string): number {
  let c = 0;
  let pos = seq.indexOf(f);
  while (pos !== -1) {
    c++;
    pos = seq.indexOf(f, pos + 1);
  }
  return c;
}

let out = freq(1) + freq(2);
for (const f of ["GGT", "GGTA", "GGTATT", "GGTATTTTAATT", "GGTATTTTAATTTATAGT"]) {
  out += count(f) + "\t" + f + "\n";
}
process.stdout.write(out);
